describe('ChatOrchestrator onError for undefined rejection', () => {
  it('wraps undefined for onError and rethrows the original value', async () => {
    const provider: AIProvider = {
      // eslint-disable-next-line require-yield
      async *sendMessage(): AsyncGenerator<MessageChunk> {
        throw undefined;
      },
      async generateStructured<T>(): Promise<T> {
        return {} as T;
      },
    };
    const session: ChatSession = {
      sessionId: 'test-session',
      userId: 'user-1',
      entries: [{role: 'user', content: 'hello', timestamp: new Date().toISOString()}],
    };
    const promptBuilder = new PromptBuilder({identity: 'You are a test assistant.'});
    let receivedError: Error | undefined;
    const hooks: OrchestratorHooks = {
      onError: async (_session, error) => {
        receivedError = error;
      },
    };
    const orchestrator = createChatOrchestrator(provider, promptBuilder, undefined, {hooks});

    const thrown = await orchestrator.processMessage(session).then(
      () => 'resolved',
      reason => reason
    );

    expect({
      thrown,
      receivedError: receivedError instanceof Error,
      message: receivedError?.message,
      hasCause: receivedError !== undefined && Object.hasOwn(receivedError, 'cause'),
      cause: receivedError?.cause,
    }).toEqual({
      thrown: undefined,
      receivedError: true,
      message: 'undefined',
      hasCause: true,
      cause: undefined,
    });
